// Filtrar citas en las proximas 24 horas
const items = $input.all();
const now = new Date();
const next24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);

const upcomingAppointments = items.filter(item => {
  const app = item.json;
  if (!app.scheduledStartAt || app.statusCode !== 'APPROVED') return false;
  const start = new Date(app.scheduledStartAt);
  return start >= now && start <= next24h;
});

return upcomingAppointments.map(item => ({
  json: {
    ...item.json,
    reminderSubject: `Recordatorio de Cita Médica FCV - ${item.json.specialtyName}`,
    reminderHtml: `
      <div style="font-family: Arial, sans-serif; color: #1e293b; max-width: 600px; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px;">
        <h2 style="color: #0284c7; margin-top: 0;">Fundación Cardiovascular de Colombia</h2>
        <p>Estimado(a) paciente,</p>
        <p>Le recordamos su cita médica programada:</p>
        <ul>
          <li><strong>Especialidad:</strong> ${item.json.specialtyName}</li>
          <li><strong>Profesional:</strong> Dr(a). ${item.json.professionalName}</li>
          <li><strong>Sede:</strong> ${item.json.locationName}</li>
          <li><strong>Fecha y Hora:</strong> ${item.json.scheduledStartAt}</li>
        </ul>
        <p style="color: #64748b; font-size: 12px;">Este es un mensaje automático de laboratorio con datos sintéticos.</p>
      </div>
    `
  }
}));

const sentCount = $input.all().length;
return [{
  json: {
    status: 'SUCCESS',
    remindersSent: sentCount,
    executedAt: new Date().toISOString()
  }
}];
